/// Tibetan (Phugpa), Bhutanese and Mongolian lunisolar calendar conversions.
///
/// Start with [KharagCalendar]:
///
/// ```dart
/// final losar = KharagCalendar.phugpa().fromDate(DateTime(2026, 2, 18));
/// print(losar); // TibetanDate(phugpa 2026-1-1 linearDay 1)
/// ```
///
/// The engines are a port of the traditional engines of the Python library
/// caltib (https://github.com/gantemur/caltib) and are tested for
/// bit-for-bit equality against data generated by it.
library;

export 'src/julian_day.dart'
    show dateTimeToJdn, gregorianToJdn, jdnToDateTime, jdnToGregorian;
export 'src/kharag_calendar_base.dart';
export 'src/tibetan_date.dart';
export 'src/tradition.dart' show Tradition;
